import sys,os;sys.path.insert(0,os.path.dirname(os.path.abspath(__file__)))
from paths import *
import http.server,threading,functools,json
from playwright.sync_api import sync_playwright
from fake2 import FAKE2
srv=http.server.ThreadingHTTPServer(('127.0.0.1',8814),functools.partial(type('Q',(http.server.SimpleHTTPRequestHandler,),{'log_message':lambda *a:None}),directory=APP));threading.Thread(target=srv.serve_forever,daemon=True).start()
res=[];errs=[]
def check(n,c,x=''):res.append(bool(c));print(('OK   ' if c else 'FALLA'),n,x)
VER=json.load(open(os.path.join(APP,'version.json'),encoding='utf-8'))
SEED="window.__seed={futbol_personal_jugadores:[{id:'j1',user_id:'u1',nombre:'Leo',dorsal:10,modalidad:'f7'}],futbol_personal_partidos:[],perfiles:[{id:'u1',plan:'gratis'}]};"
def abre(b,ctx=None,android=False,ls=None):
    ls=dict({'mf_ftut:campo':'1','mf_ftut:liga':'1','mf_ftut:mapa':'1','mf_ftut:entdir':'1','mf_ftut:anograb':'1','mf_ftut:camext':'1','mf_ftut:sigue':'1','mf_ftut:lente':'1','mf_ftut:enviar':'1','mf_ftut:porteros':'1','mf_ftut:prevencion':'1','mf_ftut:jugadas':'1'},**(ls or {}))  # el aviso de tutoriales se prueba en ftut.py
    ctx=ctx or b.new_context(viewport={'width':390,'height':844},service_workers='block')
    pg=ctx.new_page();pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.add_init_script("window.__probarNovedades=true;"+SEED+(("try{if(!sessionStorage.getItem('__ls')){sessionStorage.setItem('__ls','1');"+"".join("localStorage.setItem(%r,%r);"%kv for kv in ls.items())+"}}catch(e){}") if ls else "")+("Object.defineProperty(document,'referrer',{get:()=>'android-app://com.monetizaplus.mifutbol'});" if android else ""))
    pg.route('**/supabase.js',lambda r:r.fulfill(content_type='application/javascript',body=FAKE2))
    entra(pg)
    return ctx,pg
def entra(pg):
    pg.goto('http://127.0.0.1:8814/index.html')
    pg.fill('input[name=email]','ana@x.es');pg.fill('input[name=password]','secreto1');pg.click('[data-auth=login]');pg.wait_for_selector('#app:not(.hidden)')
    pg.wait_for_timeout(1200)
# v11.46: solo salen las novedades que el usuario no ha visto (cada novedad lleva su versión "v")
NOV=VER['novedades'];ACT=VER['version']
def vk(v):return [int(x) for x in v.split('.')]
check('todas las novedades de version.json llevan su versión',all(x.get('v') for x in NOV))
check('las novedades están de la más nueva a la más antigua',[vk(x['v']) for x in NOV]==sorted([vk(x['v']) for x in NOV],reverse=True))
check('las de esta versión van arriba',NOV[0]['v']==ACT)
ANT=[x['v'] for x in NOV if x['v']!=ACT][0]  # la versión anterior que tiene novedades
def de(v):return [x['texto'] for x in NOV if x['v']==v]
def txt(pg):return pg.locator('#infoBody').inner_text() if pg.locator('#info').is_visible() else ''
def tit(pg):return pg.locator('#infoTitle').inner_text() if pg.locator('#info').is_visible() else ''
def tiene(body,t):return t[:60].replace('✅ ','') in body
with sync_playwright() as p:
    b=p.chromium.launch()
    # 1) Venía de la versión anterior: solo lo de esta versión
    ctx,pg=abre(b,ls={'mf_novedades_visto':ANT})
    t=tit(pg);body=txt(pg)
    check('al entrar tras actualizar salen las novedades',('novedades' in t.lower()) and ACT in t,t)
    check('salen las de esta versión',all(tiene(body,x) for x in de(ACT)),body[:200])
    check('y no las de la versión que ya tenía (%s)'%ANT,not any(tiene(body,x) for x in de(ANT)))
    check('ni las más antiguas (11.26)',not any(tiene(body,x) for x in de('11.26')))
    check('sin títulos de versión si solo hay una',pg.locator('#infoBody h3.nov-v').count()==0)
    check('dice que es lo nuevo de esta versión','Esto es lo nuevo' in body)
    pg.click('#info [data-acct=novedades-ok]');pg.wait_for_timeout(200)
    check('«Entendido» las cierra',pg.locator('#info').is_hidden())
    check('se guarda la versión vista',pg.evaluate("localStorage.getItem('mf_novedades_visto')")==ACT)
    entra(pg)
    check('no vuelven a salir en la misma versión',pg.locator('#info').is_hidden())
    pg.click('#acct');pg.click('#info [data-acct=novedades]');pg.wait_for_timeout(500)
    body=txt(pg)
    check('se pueden ver otra vez desde Mi cuenta','novedades' in tit(pg).lower() and all(tiene(body,x) for x in de(ACT)) and not any(tiene(body,x) for x in de(ANT)))
    pg.click('#info [data-acct=novedades-todas]');pg.wait_for_timeout(500)
    body=txt(pg)
    check('«Ver novedades anteriores» enseña todo el historial',tit(pg).lower()=='todas las novedades' and all(tiene(body,x['texto']) for x in NOV),tit(pg))
    check('agrupado por versión, de la más nueva a la más antigua',pg.locator('#infoBody h3.nov-v').all_inner_texts()[:2]==['VERSIÓN '+ACT,'VERSIÓN '+ANT] or pg.locator('#infoBody h3.nov-v').all_inner_texts()[:2]==['Versión '+ACT,'Versión '+ANT],pg.locator('#infoBody h3.nov-v').all_inner_texts()[:3])
    check('en el historial siguen las de la v11.26 (horizontal, Portero, discontinua)',all(w in body for w in ('horizontal','Portero','discontinua','fichas más pequeñas')))
    check('y las de la v11.44 (campo en el mapa)',all(w in body for w in ('el campo en el mapa','Buscar en el mapa','Cómo llegar','Mis campos','OpenStreetMap')))
    check('y las de la v11.45 (campo desde la federación)',all(tiene(body,x) for x in de('11.45')))
    check('y las de la v11.48 (si te llaman no se corta nada)',all(w in body for w in ('Si te llaman, no se corta nada','Cámara o sonido en pausa','No molestar')))
    check('y las de la v11.49 (mapa de calor después del partido)',all(w in body for w in ('Mapa de calor también después del partido','Dónde fue cada acción','2 partidos al mes')))
    check('v11.71: lente 0,5x con su tutorial',all(w in body for w in ('Lente 0,5x o 1x','más campo','3 partidos o entrenos al mes','desde su enlace')) and pg.locator('#infoBody [data-ftut=lente]').count()>=1)
    check('v11.70: si no puedes entrar, la app dice por qué',all(w in body for w in ('Si no puedes entrar','Actualizar Chrome','Actualizar WebView','Reparar','tablet apaisada')))
    check('v11.69: el anotador también elige el encuadre',all(w in body for w in ('El anotador también elige el','Abierto','Medio','Cerrado','móvil del trípode')))
    check('v11.68: «Seguir la jugada» con más campo y encuadre',all(w in body for w in ('con más campo y mejor imagen','muy pillado','Encuadre','Abierto','Cerrado')))
    check('v11.67: «Seguir la jugada» más tranquilo',all(w in body for w in ('más tranquilo y certero','pasa pegada al móvil','últimos 2 segundos')))
    check('v11.66: el anotador abre la cámara del móvil del trípode',all(w in body for w in ('Dejar en el trípode','Abrir la cámara','Abrir y emitir para la familia')) and pg.locator('#infoBody [data-ftut=anograb]').count()>=1)
    check('v11.65: la pantalla no se apaga esperando al anotador',all(w in body for w in ('esperando al anotador','Pantalla encendida','Toca la pantalla una vez')))
    check('v11.64: jugadas más largas, porteros y prevención, con sus tutoriales',all(w in body for w in ('8-10 segundos','Porteros y goles por minutos','prevención de lesiones y de arrancada')) and all(pg.locator('#infoBody [data-ftut=%s]'%k).count()>=1 for k in ('jugadas','porteros','prevencion')))
    check('y la de la v11.63 (árbol del club sin textos encimados)',all(w in body for w in ('Árbol del club más claro','fila aparte')))
    check('y la de la v11.62 (seguir la jugada desde el anotador)',all(w in body for w in ('también desde el anotador','Ver todo el campo')))
    check('y la de la v11.59 (cámara que sigue la jugada)',all(w in body for w in ('Seguir la jugada','estilo Veo','2 partidos o entrenos al mes')) and pg.locator('#infoBody [data-ftut=sigue]').count()==1)
    check('y las de la v11.57 (buscar mi equipo en la federación)',all(w in body for w in ('Buscar mi equipo','filtrada por la categoría','Volver a probar')))
    check('y la de la v11.58 (barra flotando en iPad antiguos)',all(w in body for w in ('Arreglo en iPad antiguos','barra de abajo','flotando')))
    check('y la de la v11.55 (cámara externa)',all(w in body for w in ('Cámara externa en el directo','XbotGo','YouTube','2 partidos o entrenos al mes')))
    check('y la de la v11.54 (guardar en Fotos en iPhone)',all(w in body for w in ('Guardar en Fotos','Archivos › Descargas','Parar grabación')))
    check('y la de la v11.53 (grabación desde el anotador)',all(w in body for w in ('el anotador también lleva la grabación','Pausar grabación','Reanudar grabación')))
    check('y la de la v11.52 (entreno en directo)',all(w in body for w in ('emite el entreno en directo','Enviar el enlace','2 entrenos en directo al mes')))
    check('y la de la v11.51 (cuántos te siguen en el directo)',all(w in body for w in ('Cuántos están viendo el directo','personas están viendo el directo','también lo ven')))
    check('y las de la v11.50 (pantalla encendida en el directo, imagen derecha)',all(w in body for w in ('la pantalla se apagaba al emitir el directo','Bloqueo automático','Imagen: Automática','La familia ve mejor el directo')))
    check('la novedad del mapa después del partido trae su tutorial',pg.locator('#infoBody [data-ftut=mapa]').count()==1)
    check('y las de la v11.41 (clasificación de la liga)',all(w in body for w in ('Nueva clasificación de la liga','Federación Andaluza','4 días al mes')))
    check('la novedad del campo en el mapa trae su tutorial',pg.locator('#infoBody [data-ftut=campo]').count()==1)
    check('y la de la liga también',pg.locator('#infoBody [data-ftut=liga]').count()==1)
    pg.click('#closeInfo');pg.wait_for_timeout(200)
    pg.click('#acct');pg.wait_for_timeout(300)
    check('Mi cuenta muestra el precio anual','3,33 €/mes' in pg.locator('#infoBody').inner_text().lower())
    check('Mi cuenta tiene «Tutoriales paso a paso»',pg.locator('#info [data-info=tutoriales]').count()==1)
    ctx.close()
    # 2) Llevaba varias versiones sin abrirla: todo lo que no tenía, y nada de lo que ya tenía
    ctx,pg=abre(b,ls={'mf_novedades_visto':'11.41'})
    t=tit(pg);body=txt(pg)
    check('si venía de la 11.41 el título lo dice','desde tu última versión' in t.lower(),t)
    check('y dice qué versión tenía','Tenías la versión 11.41' in body,body[:120])
    falt=[x['texto'] for x in NOV if vk(x['v'])>vk('11.41')]
    check('salen todas las de las versiones que se saltó (11.42 a %s)'%ACT,all(tiene(body,x) for x in falt),len(falt))
    check('no sale nada de la 11.41 ni de antes',not any(tiene(body,x['texto']) for x in NOV if vk(x['v'])<=vk('11.41')))
    hs=pg.locator('#infoBody h3.nov-v').all_inner_texts()
    check('con un título por versión, de la más nueva a la más antigua',[h.lower() for h in hs]==['versión '+v for v in sorted({x['v'] for x in NOV if vk(x['v'])>vk('11.41')},key=vk,reverse=True)],hs)
    ctx.close()
    # 3) Sin «visto» pero con la versión abierta antes (mf_version_abierta)
    ctx,pg=abre(b,ls={'mf_version_abierta':'11.43'})
    body=txt(pg)
    check('con solo la versión abierta antes (11.43) salen la 11.44 y la %s'%ACT,all(tiene(body,x) for x in de('11.44')+de(ACT)) and not any(tiene(body,x) for x in de('11.43')),body[:150])
    ctx.close()
    # 4) Sin saber qué versión tenía: solo lo de esta versión
    ctx,pg=abre(b)
    body=txt(pg)
    check('sin saber qué versión tenía, solo lo de esta versión',all(tiene(body,x) for x in de(ACT)) and not any(tiene(body,x) for x in de('11.44')),body[:150])
    ctx.close()
    ctx,pg=abre(b,android=True,ls={'mf_novedades_visto':'11.43'})
    body=txt(pg)
    check('en la app de Android también salen las novedades','el campo en el mapa' in body and not any(tiene(body,x) for x in de('11.43')),body[:80])
    b.close()
print('PASS' if all(res) and not errs else 'FAIL',sum(res),'/',len(res),errs)
sys.exit(0 if all(res) and not errs else 1)
